SELECT YEAR, AVG(Weight) AS Average_Weight
FROM cars_data
GROUP BY YEAR;

SELECT DISTINCT T2.Template_Description 
FROM Documents AS T1 
JOIN Templates AS T2 ON T1.Template_ID = T2.Template_ID;

SELECT D.Document_Name, D.Document_ID
FROM Documents D
WHERE D.Document_Description LIKE '%w%';

SELECT City, COUNT(*) AS Number_of_Employees
FROM employee
GROUP BY City;

SELECT AVG(Num_of_Staff) 
FROM museum 
WHERE Open_Year < '2009';

SELECT student_id, COUNT(*) AS num_likes
FROM Likes
GROUP BY student_id;

SELECT Record_Company, COUNT(*) AS Number_of_Orchestras
FROM orchestra
GROUP BY Record_Company;

SELECT c.Name, o.Orchestra
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT Record_Company, COUNT(*) AS Number_of_Operations
FROM orchestra
GROUP BY Record_Company;

SELECT COUNT(PetID) FROM Has_Pet WHERE StuID IN (
    SELECT StuID FROM Student WHERE Age > 20
)

SELECT StuID, COUNT(PetID) AS num_pets
FROM Has_Pet
GROUP BY StuID;

SELECT Citizenship, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Citizenship;
